  state.setText(changing?"Применяем настройки…":!error.isEmpty()?error:!fresh()?"Нет свежих данных":mode.equals("off")?"Выключено":!s.optString("state").equals("ready")?"Восстанавливаем USB…":s.optBoolean("carrier")?"Клиент подключён":"Кабель готов · ждём подключение");
