  syncing=true;ethernet.setChecked(s.optBoolean("ethernet_lan"));syncing=false;enabled(ethernet,available);
  ethernetState.setText(changing?"Применяем настройки…":!fresh()?"Нет свежих данных":ethernetSummary(s));ethernetState.setTextColor(fresh()&&s.optBoolean("ethernet_lan")&&s.optBoolean("ethernet_carrier")?MainActivity.ACCENT:MainActivity.MUTED);
