  a.body.addView(label("Защита сети"));a.gap(a.body,8);securityChoices=new Button[4];String[] keys={"wpa2","wpa2-wpa3","wpa3","open"};for(int row=0;row<2;row++){LinearLayout choices=new LinearLayout(a);a.body.addView(choices);for(int col=0;col<2;col++){int i=row*2+col;String key=keys[i];securityChoices[i]=action(choices,protection(key),false,()->{security=key;editorChanged();});}equal(choices);a.gap(a.body,8);}
