 String validation(){String ssid=name.getText().toString(),pass=password.getText().toString();if(ssid.trim().isEmpty()||ssid.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>32)return "Имя сети: от 1 до 32 байт UTF-8";for(char c:ssid.toCharArray())if(Character.isISOControl(c))return "Уберите управляющие символы из имени";if(!security.equals("open")){if(pass.length()<8||pass.length()>63)return "Пароль: от 8 до 63 символов";for(char c:pass.toCharArray())if(c<32||c>126)return "Пароль: латинские буквы, цифры и знаки ASCII";}return "";}
