 void showAccess(){a.startPage("wifi-access","Подключение к Wi-Fi",()->show());a.body.addView(a.text("Готовим QR-код…",15,MainActivity.MUTED));a.worker.execute(()->{try{JSONObject cfg=new JSONObject(a.api("/droidwrt/hotspot-access",null));String ssid=cfg.getString("ssid"),pass=cfg.getString("password"),security=cfg.optString("security");String type=security.equals("open")?"nopass":security.equals("wpa3")?"SAE":"WPA";String qr="WIFI:T:"+type+";S:"+escape(ssid)+";"+(security.equals("open")?"":"P:"+escape(pass)+";")+";";java.util.Map<com.google.zxing.EncodeHintType,Object> hints=new java.util.HashMap<>();hints.put(com.google.zxing.EncodeHintType.CHARACTER_SET,"UTF-8");com.google.zxing.common.BitMatrix matrix=new com.google.zxing.qrcode.QRCodeWriter().encode(qr,com.google.zxing.BarcodeFormat.QR_CODE,512,512,hints);Bitmap bitmap=Bitmap.createBitmap(512,512,Bitmap.Config.RGB_565);for(int y=0;y<512;y++)for(int x=0;x<512;x++)bitmap.setPixel(x,y,matrix.get(x,y)?0xff000000:0xffffffff);a.runOnUiThread(()->{if(!a.page.equals("wifi-access"))return;a.body.removeAllViews();a.intro(ssid,frequency(cfg.optString("band"))+" · "+protection(security));ImageView image=new ImageView(a);image.setImageBitmap(bitmap);image.setContentDescription("QR-код подключения к Wi-Fi");LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(a.dp(270),a.dp(270));lp.gravity=Gravity.CENTER_HORIZONTAL;a.body.addView(image,lp);a.gap(a.body,18);a.note(status().optBoolean("hotspot")?"Отсканируйте камерой другого устройства.":"Точка доступа выключена. Включите её на экране раздачи перед подключением.");if(!security.equals("open")){TextView password=a.text("••••••••",21,MainActivity.FG);a.body.addView(password);a.gap(a.body,10);Button reveal=a.button("Показать пароль",()->{});reveal.setOnClickListener(v->{password.setText(pass);password.setTextIsSelectable(true);reveal.setVisibility(View.GONE);});}if(security.equals("wpa3"))a.note("Если камера не распознаёт WPA3, подключитесь вручную по имени сети и паролю.");});}catch(Exception e){a.runOnUiThread(()->{if(a.page.equals("wifi-access"))a.showError("Не удалось получить параметры Wi-Fi",()->show());});}});}
